/* @lc app=leetcode id=1349 lang=kotlin */
class Solution { fun maxStudents(seats: Array<CharArray>): Int = (0 until seats.size).fold(IntArray(1 shl seats[0].size) { -1 }.apply { this[0] = 0 }) { dp, r -> seats[r].indices.fold(0) { a, c -> if (seats[r][c] == '.') a or (1 shl c) else a }.let { valid -> IntArray(1 shl seats[0].size) { -1 }.also { nextDp -> (0 until (1 shl seats[0].size)).filter { mask -> (mask and valid) == mask && (mask and (mask shr 1)) == 0 }.forEach { mask -> (0 until (1 shl seats[0].size)).filter { prev -> dp[prev] != -1 && (mask and (prev shr 1)) == 0 && (mask and (prev shl 1)) == 0 }.forEach { prev -> nextDp[mask] = maxOf(nextDp[mask], dp[prev] + Integer.bitCount(mask)) } } } } }.maxOrNull() ?: 0 }